import ast

RANK = {ast.Pow: 3, ast.Mult: 2, ast.Div: 2, ast.Add: 1, ast.Sub: 1}

def ready(node):
    return isinstance(node, ast.BinOp) and all(isinstance(x, ast.Constant) for x in (node.left, node.right))

def pick(tree):
    """Brackets first, then powers, then x and / from the left, then + and - from the left."""
    best = None
    parent = {child: node for node in ast.walk(tree) for child in ast.iter_child_nodes(node)}
    for node in ast.walk(tree):
        if ready(node):
            up = parent.get(node)
            in_brackets = isinstance(up, ast.BinOp) and RANK[type(up.op)] > RANK[type(node.op)]
            key = (-(4 if in_brackets else RANK[type(node.op)]), node.col_offset)
            if best is None or key < best[0]:
                best = (key, node)
    return best[1] if best else None

class Fold(ast.NodeTransformer):
    def __init__(self, target): self.target = target
    def visit_BinOp(self, node):
        self.generic_visit(node)
        if node is self.target:
            value = eval(compile(ast.Expression(node), "", "eval"))
            if isinstance(value, float) and value.is_integer():
                value = int(value)
            return ast.copy_location(ast.Constant(value), node)
        return node

def show_steps(expression):
    tree = ast.parse(expression, mode="eval")
    print(expression)
    while (node := pick(tree)) is not None:
        tree = ast.fix_missing_locations(Fold(node).visit(tree))
        tree = ast.parse(ast.unparse(tree), mode="eval")   # re-parse so positions stay honest
        print("=", ast.unparse(tree))

show_steps("3 + 4 * 2 ** 2 - (6 - 1) / 5")
